    alunos = Aluno.objects.filter(data_inicio_ciclo__isnull=True, matriz__estrutura__proitec=False, turmaminicurso__isnull=True).only('id')
    alunos_para_atualizar = []
    for aluno in tqdm.tqdm(alunos):
        turma = Turma.objects.filter(matriculaperiodo__aluno_id=aluno.id).select_related('calendario_academico').only('calendario_academico__data_inicio').order_by('calendario_academico__data_inicio')
