    Aluno.objects.bulk_update(alunos_para_atualizar, ['data_inicio_ciclo'])

    # Aluno regular sem turma
    alunos = Aluno.objects.filter(data_inicio_ciclo__isnull=True,matriz__estrutura__proitec=False,turmaminicurso__isnull=True).only('id')
