    alunos = Aluno.objects.filter(data_inicio_ciclo__isnull=True,participanteturmaminicurso__minicurso__ch_total__gte=CARGA_HORARIA_BASE_MINICURSO).prefetch_related(turmas_prefetch)
    alunos_para_atualizar = []
